// ServiceByName returns a service by its symbolic name.
func ServiceByName(name string) (Service, bool) {
	for _, service := range Services {
		if service.Name == name {
			return service, true
		}
	}
	return Service{}, false
}

// ServiceByModule returns a service by its WebAssembly import module.
func ServiceByModule(module string) (Service, bool) {
	for _, service := range Services {
		if service.Module == module {
			return service, true
		}
	}
	return Service{}, false
}

// IsServiceModule reports whether module is one of the declared service modules.
func IsServiceModule(module string) bool {
	_, ok := ServiceByModule(module)
	return ok
}

// ServiceMethodByID returns one method within a service.
func ServiceMethodByID(serviceName string, id uint32) (ServiceMethod, bool) {
	service, ok := ServiceByName(serviceName)
	if !ok {
		return ServiceMethod{}, false
	}
	for _, method := range service.Methods {
		if method.ID == id {
			return method, true
		}
	}
	return ServiceMethod{}, false
}

// ServiceMethodByName returns one method within a service by name.
func ServiceMethodByName(serviceName, name string) (ServiceMethod, bool) {
	service, ok := ServiceByName(serviceName)
	if !ok {
		return ServiceMethod{}, false
	}
	for _, method := range service.Methods {
		if method.Name == name {
			return method, true
		}
	}
	return ServiceMethod{}, false
}

// HostFunction returns the generated signature for a permitted import.
// Every service module imports exactly one function, ServiceCallFunction.
func HostFunction(module, name string) (Function, bool) {
	if module == HostModuleName {
		for _, function := range HostFunctions {
			if function.Name == name {
				return function, true
			}
		}
		return Function{}, false
	}
	if name == ServiceCallFunction && IsServiceModule(module) {
		return ServiceCallSignature, true
	}
	return Function{}, false
}

// AllowsHostImport reports whether module/name is in the v1 import allowlist.
func AllowsHostImport(module, name string) bool {
	_, ok := HostFunction(module, name)
	return ok
}

